+  async list(opts?: { limit?: number; offset?: number; status?: TaskRegistryEntry["status"] }): Promise<TaskRegistryEntry[]> {
+    // Use a simple strategy: load a broad list, then apply server-side filtering
+    // to satisfy status filters and pagination requirements.
+    const limit = opts?.limit ?? 20
+    const offset = opts?.offset ?? 0
+
+    // Load all IDs to reliably apply status filter
+    const allIds = await this.redis.zrevrange(this.INDEX_KEY, 0, -1)
     const entries: TaskRegistryEntry[] = []
-    for (const id of ids) {
+    for (const id of allIds) {
       const entry = await this.get(id)
       if (entry) entries.push(entry)
     }
-    return entries
+
+    let result = entries
+    if (opts?.status) {
+      result = result.filter((e) => e.status === opts.status)
+    }
+
+    // Apply pagination after filtering
+    const start = Math.max(0, offset)
+    const end = start + limit
+    return result.slice(start, end)
+  }
+
+  async count(status?: TaskRegistryEntry["status"]): Promise<number> {
+    const ids = await this.redis.zrevrange(this.INDEX_KEY, 0, -1)
+    if (!status) return ids.length
+    let c = 0
+    for (const id of ids) {
+      const e = await this.get(id)
+      if (e?.status === status) c++
+    }
+    return c
+  }
+
+  async search(query: string, opts?: { limit?: number }): Promise<TaskRegistryEntry[]> {
+    const limit = Math.min(opts?.limit ?? 20, 50)
+    const ids = await this.redis.zrevrange(this.INDEX_KEY, 0, 49)
+    const q = query.toLowerCase()
+    const results: TaskRegistryEntry[] = []
+    for (const id of ids) {
+      const e = await this.get(id)
+      if (!e) continue
+      const hay = `${e.issueTitle} ${e.issueUrl}`.toLowerCase()
+      if (hay.includes(q)) {
+        results.push(e)
+        if (results.length >= limit) break
+      }
+    }
+    return results
+  }
+
+  async aggregateStats(): Promise<{ total: number; queued: number; running: number; done: number; failed: number; totalCostUsd?: number }> {
+    const ids = await this.redis.zrevrange(this.INDEX_KEY, 0, 199)
+    let total = 0
+    let queued = 0
+    let running = 0
+    let done = 0
+    let failed = 0
+    let totalCostUsd = 0
+    for (const id of ids) {
+      const e = await this.get(id)
+      if (!e) continue
+      total++
+      switch (e.status) {
+        case "queued":
+          queued++
+          break
+        case "running":
+          running++
+          break
+        case "done":
+          done++
+          break
+        case "failed":
+          failed++
+          break
+      }
+      const m = await this.getMetrics(id)
+      totalCostUsd += m?.costUsd ?? 0
+    }
+    return { total, queued, running, done, failed, totalCostUsd }
   }

